class Solution { private boolean feasible(int[] position,int m,int distance){int count=1,last=position[0];for(int value:position)if(value-last>=distance){last=value;if(++count>=m)return true;}return false;}public int maxDistance(int[] position,int m){Arrays.sort(position);int left=1,right=position[position.length-1]-position[0];while(left<right){int middle=left+(right-left+1)/2;if(feasible(position,m,middle))left=middle;else right=middle-1;}return left;} }
